use super::is_absolute::is_absolute;

/// Whether a `read_file` `target` sits under one of the read-only harvest roots (#3530) — mirrors
/// `isUnderHarvestRoot` in `fsConfine.ts` and the `__bsc_read_harvestable` shell helper. Same
/// conservatism as [`super::path_confined`]: only an ABSOLUTE path with no `..` segment, under a listed
/// root (a shared prefix is not containment). Empty roots contribute nothing.
pub(crate) fn under_any_harvest_root(roots: &[String], target: &str) -> bool {
    if target.is_empty() || !is_absolute(target) {
        return false;
    }
    let norm = target.replace('\\', "/");
    if norm.split('/').any(|seg| seg == "..") {
        return false;
    }
    roots.iter().any(|root| {
        if root.is_empty() {
            return false;
        }
        let r = root.replace('\\', "/");
        let r = r.trim_end_matches('/');
        norm == r || norm.starts_with(&format!("{r}/"))
    })
}
